interface Product {
  image: string;
  id: string;
  name: string;
  description: string;
  brand: string;
  price: string;
  originalPrice: string | null;
  category: string;
  rating: string;
  reviewCount: number;
  inStock: boolean;
  badge: string | null;
  nonExistentProperty?: string; // Added to resolve TS2339
}

export const ProductCard = ({ product }: { product: Product }) => {
  return (
    <div className="product-card">
      <h3>{product.name}</h3>
      {/* Safely render the property if it exists */}
      {product.nonExistentProperty && (
        <span className="extra-info">{product.nonExistentProperty}</span>
      )}
    </div>
  );
};

